size_t GetQuantumExtent(const Image *image, const QuantumInfo *quantum_info, const QuantumType quantum_type)
{
  register size_t
    extent = 0;

  if (quantum_info == (QuantumInfo *) NULL)
    return(extent);
  if (quantum_info->signature != MagickCoreSignature)
    return(extent);
  switch (quantum_type)
  {
    case RedQuantum:
    case GreenQuantum:
    case BlueQuantum:
    case IndexQuantum:
    case TrueIndexQuantum:
    {
      extent = image->columns * sizeof(*quantum_info->quantum);
      break;
    }
    case OpacityQuantum:
    {
      extent = image->columns * sizeof(*quantum_info->opacity);
      break;
    }
    case RGBQuantum:
    {
      extent = image->columns * 3 * sizeof(*quantum_info->quantum);
      break;
    }
    case RGBAQuantum:
    {
      extent = image->columns * 4 * sizeof(*quantum_info->quantum);
      break;
    }
    default:
    {
      break;
    }
  }
  return(extent);
}

